style.css:
/* Change page background */
body {
  background-color: #1e1e1e;
  color: #ffffff;
  font-family: Arial, sans-serif;
}

/* Style headings */
h1, h2, h3 {
  color: #ff9f6b;
}

/* Style buttons */
button {
  background-color: #ff9f6b;
  color: #000;
  border: none;
  padding: 10px 16px;
  border-radius: 8px;
  cursor: pointer;
}

button:hover {
  background-color: #ff7f3f;
}

/* Style input fields */
input, textarea {
  background-color: #2a2a2a;
  color: #fff;
  border: 1px solid #444;
  border-radius: 6px;
  padding: 8px;
}
